            <input id="new-task-title-${task.id}" name="title" type="text" autocomplete="off"${project.archived ? ' disabled' : ''}>
            <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
          </div>
        </form>
      </li>`).join('')}</ul>`);
}

function redirectToProject(response, projectId, filter, priority, range) {
  const query = new URLSearchParams({ filter });
  if (priority !== 'All') query.set('priorityFilter', priority);
  if (range.from) query.set('dueFrom', range.from);
  if (range.through) query.set('dueThrough', range.through);
  response.writeHead(303, { Location: `/projects/${projectId}?${query}` });
  response.end();
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    const path = url.pathname;
    // Range state is local to this request; all responses retain its applied view.
    let range = { from: '', through: '' };
    const renderProject = (project, filter, priority, error = '') =>
      projectPage(project, filter, priority, error, range);
    const redirectProject = (id, filter, priority) =>
      redirectToProject(response, id, filter, priority, range);
    if (request.method === 'GET' && path === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (request.method === 'GET' && path === '/') {
      sendHtml(response, 200, projectList('', projectFilter(url.searchParams.get('filter'))));
      return;
    }
    if (request.method === 'POST' && path === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 400, projectList('Project name is required'));
        return;
      }
      store.create(name);
      response.writeHead(303, { Location: '/' });
      response.end();
      return;
    }
    const defaultPriorityMatch = /^\/projects\/([1-9]\d*)\/default-priority$/.exec(path);
    if (request.method === 'POST' && defaultPriorityMatch) {
      const id = Number(defaultPriorityMatch[1]);
      const project = Number.isSafeInteger(id) ? store.find(id) : undefined;
      if (project) {
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        range = appliedDueRange(form);
        if (project.archived) {
          sendHtml(response, 409, renderProject(project, filter, priority, 'Archived project is read-only'));
          return;
        }
        const defaultPriority = form.get('priority');
        if (!['Low', 'Normal', 'High'].includes(defaultPriority)) {
          sendHtml(response, 400, renderProject(project, filter, priority, 'Invalid task priority'));
          return;
        }
        store.setDefaultTaskPriority(id, defaultPriority);
        redirectProject(id, filter, priority);
        return;
      }
    }
    const renameMatch = /^\/projects\/([1-9]\d*)\/rename$/.exec(path);
    if (request.method === 'POST' && renameMatch) {
      const id = Number(renameMatch[1]);
      const project = Number.isSafeInteger(id) ? store.find(id) : undefined;
      if (project) {
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        range = appliedDueRange(form);
        if (project.archived) {
          sendHtml(response, 409, renderProject(project, filter, priority, 'Archived project is read-only'));
          return;
        }
        const name = (form.get('name') || '').trim();
        if (!name) {
          sendHtml(response, 400, renderProject(project, filter, priority, 'Project name is required'));
          return;
        }
        store.rename(id, name);
        redirectProject(id, filter, priority);
        return;
      }
    }
    const archiveMatch = /^\/projects\/([1-9]\d*)\/(archive|restore)$/.exec(path);
    if (request.method === 'POST' && archiveMatch) {
      const id = Number(archiveMatch[1]);
      if (Number.isSafeInteger(id) && store.setArchived(id, archiveMatch[2] === 'archive')) {
        response.writeHead(303, { Location: archiveMatch[2] === 'archive' ? '/' : '/?filter=Archived' });
        response.end();
        return;
      }
    }
    const match = /^\/projects\/([1-9]\d*)$/.exec(path);
    if (request.method === 'GET' && match) {
      const id = Number(match[1]);
      const project = Number.isSafeInteger(id) ? store.find(id) : undefined;
      if (project) {
        const filter = taskFilter(url.searchParams.get('filter'));
        const priority = priorityFilter(url.searchParams.get('priorityFilter'));
        range = appliedDueRange(url.searchParams);
        if (url.searchParams.get('applyRange') === '1') {
          try {
            range = normalizeDueRange(url.searchParams.get('rangeFrom') || '', url.searchParams.get('rangeThrough') || '');
          } catch (error) {
            sendHtml(response, 400, renderProject(project, filter, priority, error.message));
            return;
          }
          redirectProject(id, filter, priority);
          return;
        }
        sendHtml(response, 200, renderProject(project, filter, priority));
        return;
      }
    }
    const taskMatch = /^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*)\/(completion|rename|priority|due-date|move))?$/.exec(path);
    if (request.method === 'POST' && taskMatch) {
      const projectId = Number(taskMatch[1]);
      const project = Number.isSafeInteger(projectId) ? store.find(projectId) : undefined;
      if (project) {
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        range = appliedDueRange(form);
        if (project.archived) {
          sendHtml(response, 409, renderProject(project, filter, priority, 'Archived project is read-only'));
          return;
        }
        if (!taskMatch[2]) {
          const title = (form.get('title') || '').trim();
          if (!title) {
            sendHtml(response, 400, renderProject(project, filter, priority, 'Task title is required'));
            return;
          }
          store.createTask(projectId, title);
        } else {
          const taskId = Number(taskMatch[2]);
          let updated = false;
          if (Number.isSafeInteger(taskId)) {
            if (taskMatch[3] === 'move') {
              const destinationId = Number(form.get('destinationId'));
              updated = store.moveTask(projectId, taskId, destinationId);
              if (!updated) {
                sendHtml(response, 400, renderProject(project, filter, priority, 'Task must move to another active project'));
                return;
              }
            } else if (taskMatch[3] === 'rename') {
              const title = (form.get('title') || '').trim();
              if (!title) {
                sendHtml(response, 400, renderProject(project, filter, priority, 'Task title is required'));
                return;
              }
              updated = store.renameTask(projectId, taskId, title);
            } else if (taskMatch[3] === 'due-date') {
              try {
                updated = store.setTaskDueDate(projectId, taskId, form.get('dueDate') || '');
              } catch (error) {
                if (error.message !== 'Due date must be a valid YYYY-MM-DD date') throw error;
                sendHtml(response, 400, renderProject(project, filter, priority, error.message));
                return;
              }
            } else if (taskMatch[3] === 'priority') {
              const taskPriority = form.get('priority');
              if (!['Low', 'Normal', 'High'].includes(taskPriority)) {
                sendHtml(response, 400, renderProject(project, filter, priority, 'Invalid task priority'));
                return;
              }
              updated = store.setTaskPriority(projectId, taskId, taskPriority);
            } else {
              updated = store.setTaskCompleted(projectId, taskId, form.get('completed') === '1');
            }
          }
          if (!updated) {
            sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
        }
        redirectProject(projectId, filter, priority);
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Not found</h1><a href="/">Projects</a>'));
  } catch (error) {
    const status = error.status || 500;
    if (status === 500) console.error(error);
    sendHtml(response, status, page('Error', `<h1>${status === 413 ? 'Request body is too large' : 'Something went wrong'}</h1>`));
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => {
      store.close();
      process.exit(0);
    });
  });
}

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { normalizeDueDate } from './dates.js';

export function openProjectStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const database = new DatabaseSync(path);
  database.exec(`
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK(length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK(length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  // Add archive state without replacing existing projects or their task IDs.
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
  }
  // Default both migrated and new tasks to Normal without changing task identity.
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
    database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))");
  }
  // Project defaults affect future tasks only; existing task priorities are untouched.
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_priority')) {
    database.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_priority IN ('Low', 'Normal', 'High'))");
  }
  // Empty dates cover both migrated tasks and future tasks.
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
    database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
  }
  // Separate project-local order from identity so moved tasks append without new IDs.
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
    database.exec(`
      BEGIN;
      ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
      UPDATE tasks SET position = id;
      COMMIT;
    `);
  }
  // Retain positions even while tasks belong elsewhere. Seed legacy current order.
  database.exec(`
    BEGIN;
    CREATE TABLE IF NOT EXISTS task_positions (
      task_id INTEGER NOT NULL REFERENCES tasks(id),
      project_id INTEGER NOT NULL REFERENCES projects(id),
      position INTEGER NOT NULL,
      PRIMARY KEY (task_id, project_id),
      UNIQUE (project_id, position)
    );
    INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
      SELECT id, project_id, position FROM tasks;
    COMMIT;
  `);

  function transaction(operation) {
    database.exec('BEGIN IMMEDIATE');
    try {
      const result = operation();
      database.exec('COMMIT');
      return result;
    } catch (error) {
      database.exec('ROLLBACK');
      throw error;
    }
  }

  const list = database.prepare(`
    SELECT p.id, p.name, p.archived, COUNT(t.id) AS total,
      COALESCE(SUM(t.completed), 0) AS completed
    FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
    WHERE p.archived = ? GROUP BY p.id ORDER BY p.id
  `);
  const find = database.prepare('SELECT id, name, archived, default_priority FROM projects WHERE id = ?');
  const updateDefaultPriority = database.prepare('UPDATE projects SET default_priority = ? WHERE id = ? AND archived = 0');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const updateName = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');

  const listTasks = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position, id');
  const insertTask = database.prepare(`
    INSERT INTO tasks (project_id, title, priority, position)
    SELECT id, ?, default_priority,
      (SELECT COALESCE(MAX(position), 0) + 1 FROM task_positions WHERE project_id = projects.id)
    FROM projects WHERE id = ? AND archived = 0
  `);
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const updateTaskTitle = database.prepare(`
    UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);

  const updateTaskPriority = database.prepare(`
    UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);

  const updateTaskDueDate = database.prepare(`
    UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);

  const rememberCreatedPosition = database.prepare(`
    INSERT INTO task_positions (task_id, project_id, position)
      SELECT id, project_id, position FROM tasks WHERE id = ?
  `);
  const eligibleMove = database.prepare(`
    SELECT id FROM tasks
    WHERE project_id = ? AND id = ? AND project_id != ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
      AND EXISTS (SELECT 1 FROM projects WHERE id = ? AND archived = 0)
  `);
  const rememberDestination = database.prepare(`
    INSERT INTO task_positions (task_id, project_id, position)
